const cursor_ts = msg.metadata.source.timestamp;
const utils = global.get("utils");
const connection = msg.metadata.connection_name;
const source = msg.metadata.source.identifier;

// Filter conditions
msg.payload = msg.payload.filter(entry => {
    if (entry.timeCreated <= cursor_ts) return false;
    if (entry.text && utils.is_bridge_message(entry.text)) return false;
    if (entry.loggedByFullName && utils.is_bridge_message(entry.loggedByFullName)) return false;
    return true;
});

if (msg.payload.length === 0) return null;

// Update timestamp
global.set(
    `parat_bridge.connections.${connection}.clients.${source}.timestamp`,
    msg.payload[msg.payload.length - 1].timeCreated
);

return msg;

// sort oldes to newest
if (!msg.payload || msg.payload.length === 0) return null;

msg.payload.sort((a, b) => a.timeCreated - b.timeCreated);
return msg;
